491	  String? _darwinPluginDirectoryName(String platform) {
492	    final PluginPlatform? platformPlugin = platforms[platform];
493	    if (platformPlugin == null ||
494	        (platform != IOSPlugin.kConfigKey && platform != MacOSPlugin.kConfigKey)) {
