  /// Validates that a plugin supports Swift Package Manager when building its
  /// example app.
  ///
  /// If the current project is a plugin's example app, this checks whether the
  /// parent plugin has Swift Package Manager support and logs a warning if it
  /// does not (fully) support it.
  void _validateExampleAppPluginSupportsSwiftPackageManager({
    required FlutterDarwinPlatform platform,
  }) {
    final Plugin? parentPlugin = _loadPluginFromExampleProject();
    if (parentPlugin == null) {
      return;
    }

    final String? warning = validatePluginSupportsSwiftPackageManager(
      parentPlugin,
      fileSystem: _fileSystem,
      platform: platform.name,
    );

    if (warning != null) {
      _logger.printWarning(warning);
    }
  }

  /// Returns the parent plugin if the current project is a plugin's example
  /// app, or `null` otherwise.
  ///
  /// The current project is considered a plugin's example app if all of the
  /// following are true:
  ///   - The project directory path ends with `example`.
  ///   - The parent directory contains a `pubspec.yaml`.
  ///   - The parent `pubspec.yaml` can be parsed.
  ///   - The parent `pubspec.yaml` declares the project as a Flutter plugin.
  ///   - The plugin name in the parent `pubspec.yaml` matches a known plugin.
  Plugin? _loadPluginFromExampleProject() {
    final Directory projectDir = _project.directory;
    if (!projectDir.path.endsWith('example')) {
      return null;
    }

    final Directory parentDir = projectDir.parent;
    final File parentPubspec = parentDir.childFile('pubspec.yaml');
    if (!parentPubspec.existsSync()) {
      return null;
    }

    final FlutterManifest? parentManifest;
    try {
      parentManifest = FlutterManifest.createFromPath(
        parentPubspec.path,
        fileSystem: _fileSystem,
        logger: _logger,
      );
    } on Exception catch (e) {
      _logger.printTrace('Failed to parse parent pubspec for SwiftPM validation: $e');
      return null;
    }

    if (parentManifest == null || !parentManifest.isPlugin) {
      return null;
    }

    final String pluginName = parentManifest.appName;
    final Iterable<Plugin> matches = _plugins.where((Plugin plugin) => plugin.name == pluginName);
    return matches.isEmpty ? null : matches.first;
  }

